class ShuntingYard:
    def __init__(self):
        self.output = []
        self.stack = []
        self.precedence = {
            '+': 1,
            '-': 1,
            '*': 2,
            '/': 2
        }
        self.associativity = {
            '+': 'L',
            '-': 'L',
            '*': 'L',
            '/': 'L'
        }

    def process_operator(self, op):
        while (self.stack and self.stack[-1] != '(' and
               (self.precedence[op] < self.precedence[self.stack[-1]] or
               (self.precedence[op] == self.precedence[self.stack[-1]] and self.associativity[op] == 'L'))):
            self.output.append(self.stack.pop())
        self.stack.append(op)

    def evaluate_rpn(self):
        stack = []
        for token in self.output:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0] if stack else 0

    def shunt(self, tokens):
        for token in tokens:
            if isinstance(token, float):
                self.output.append(token)
            elif token in self.precedence:
                self.process_operator(token)
            elif token == '(':
                self.stack.append(token)
            elif token == ')':
                while self.stack and self.stack[-1] != '(':
                    self.output.append(self.stack.pop())
                self.stack.pop()  # Pop the '(' from the stack

        while self.stack:
            self.output.append(self.stack.pop())

def tokenize(expr):
