    num = ''
    for char in expr:
        if char.isdigit() or char == '.':
            num += char
        else:
            if num:
                tokens.append(float(num))
                num = ''
            if char in "+-*/()":
                tokens.append(char)
    if num:
        tokens.append(float(num))
    return tokens

