    """Evaluate an arithmetic expression using a recursive descent parsing approach for operator precedence handling."""

    def parse_expression(index):
        nonlocal expr
        left, index = parse_term(index)
        while index < len(expr) and expr[index] in '+-':
            op = expr[index]
            index += 1
            right, index = parse_term(index)
