        while index < len(expr) and expr[index] in '*/':
            op = expr[index]
            index += 1
            right, index = parse_factor(index)
            left = apply_operator(left, op, right)
        return left, index

    def parse_factor(index):
        nonlocal expr
        if expr[index] == '(':
            index += 1
            value, index = parse_expression(index)
            index += 1  # Skip past ')'
            return value, index
        else:
