    result, _ = parse_expression(0)
    return result

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using the Shunting Yard algorithm to convert it to Reverse Polish Notation (RPN), 
    followed by evaluation of the RPN expression for handling operator precedence."""

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def to_rpn(expression: str) -> list:
        output = []
        stack = []
        number = ''

        for char in expression:
            if char.isdigit() or char == '.':
                number += char  # Build multi-digit numbers and floating-point numbers
            else:
                if number:
                    output.append(float(number))
                    number = ''
                if char in '()':
                    if char == '(':
                        stack.append(char)
                    elif char == ')':
                        while stack and stack[-1] != '(':
                            output.append(stack.pop())
                        stack.pop()  # Pop the '('
                elif char in '+-*/':
                    while (stack and precedence(stack[-1]) >= precedence(char)):
                        output.append(stack.pop())
                    stack.append(char)

        if number:
            output.append(float(number))  # For the last number

        while stack:
            output.append(stack.pop())

        return output

    def evaluate_rpn(rpn: list) -> float:
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    expr = expr.replace(' ', '')  # Remove whitespace
    rpn = to_rpn(expr)
    return evaluate_rpn(rpn)

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using a recursive descent parsing technique to parse and evaluate the expression in one pass."""

    def parse_expression(index: int) -> (float, int):
        result, index = parse_term(index)
        while index < len(expr) and expr[index] in '+-':
            operator = expr[index]
            index += 1
            term, index = parse_term(index)
            if operator == '+':
                result += term
            elif operator == '-':
