        return result, index

    def parse_term(index: int) -> (float, int):
        result, index = parse_factor(index)
        while index < len(expr) and expr[index] in '*/':
            operator = expr[index]
            index += 1
            factor, index = parse_factor(index)
            if operator == '*':
                result *= factor
            elif operator == '/':
                result /= factor
        return result, index

    def parse_factor(index: int) -> (float, int):
        if expr[index] == '(':
            index += 1  # skip '('
            result, index = parse_expression(index)
            index += 1  # skip ')'
            return result, index
        else:
            start = index
            while index < len(expr) and (expr[index].isdigit() or expr[index] == '.'):
                index += 1
            return float(expr[start:index]), index

